<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/**
 * `fuel_register` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $ID
 * @property Carbon|null $FuelDate
 * @property int|null $DriverID
 * @property int|null $VehicleID
 * @property float|null $FuelAmount
 * @property string|null $CreatedBy
 * @property Carbon|null $CreatedDate
 * @property string|null $ModifiedBy
 * @property Carbon|null $ModifiedDate
 * @property string|null $ApprovedBy
 * @property Carbon|null $ApprovedDate
 * @property string|null $ApprovedStatus
 * @property string|null $ApprovedReason
 * @property string|null $Files
 */
class FuelRegister extends Model
{
    protected $table = 'fuel_register';

    protected $primaryKey = 'ID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'ID' => 'integer',
            'FuelDate' => 'date',
            'DriverID' => 'integer',
            'VehicleID' => 'integer',
            'FuelAmount' => 'float',
            'CreatedDate' => 'date',
            'ModifiedDate' => 'date',
            'ApprovedDate' => 'date',
        ];
    }

    protected static function booted(): void
    {
        static::creating(function (FuelRegister $fuel): void {
            $fuel->CreatedDate = now();
            $fuel->CreatedBy = auth()->user()?->username;
        });
        static::updating(function (FuelRegister $fuel): void {
            $fuel->ModifiedDate = now();
            $fuel->ModifiedBy = auth()->user()?->username;
        });
    }

    public function vehicle(): BelongsTo
    {
        return $this->belongsTo(Vehicle::class, 'VehicleID', 'VehicleID');
    }
}
